// DynamicAny (org.omg.DynamicAny) with code generated by rustorb-idl -bjava:
// DynAnys of generated types, valuetypes with sharing and cycles,
// truncation, and the interfaces and exceptions of the mapping. The cases
// of interop/impls/rustorbjava/probe/interop/DynAnyProbe.java cover the
// rest of the operations.

package org.rustorb.test;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Arrays;

import AnyTest.Choice;
import AnyTest.ChoiceHelper;
import AnyTest.CountHelper;
import AnyTest.LongSeqHelper;
import AnyTest.MoneyHelper;
import AnyTest.Node;
import AnyTest.NodeHelper;
import AnyTest.OctetsHelper;
import AnyTest.Oops;
import AnyTest.OopsHelper;
import AnyTest.Point;
import AnyTest.PointHelper;
import AnyTest.Shade;
import AnyTest.ShadeHelper;
import AnyTest.ShortArrayHelper;
import ValueTest.LongBoxHelper;
import ValueTest.Pair;
import ValueTest.PairHelper;
import ValueTest.Point3;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.omg.CORBA.Any;
import org.omg.CORBA.NO_IMPLEMENT;
import org.omg.CORBA.OBJECT_NOT_EXIST;
import org.omg.CORBA.ORB;
import org.omg.CORBA.ORBPackage.InvalidName;
import org.omg.CORBA.TCKind;
import org.omg.CORBA.TypeCode;
import org.omg.DynamicAny.DynAny;
import org.omg.DynamicAny.DynAnyFactory;
import org.omg.DynamicAny.DynAnyFactoryHelper;
import org.omg.DynamicAny.DynAnyFactoryPackage.InconsistentTypeCode;
import org.omg.DynamicAny.DynAnyPackage.InvalidValue;
import org.omg.DynamicAny.DynAnyPackage.TypeMismatch;
import org.omg.DynamicAny.DynArray;
import org.omg.DynamicAny.DynEnum;
import org.omg.DynamicAny.DynEnumHelper;
import org.omg.DynamicAny.DynFixed;
import org.omg.DynamicAny.DynSequence;
import org.omg.DynamicAny.DynSequenceHelper;
import org.omg.DynamicAny.DynStruct;
import org.omg.DynamicAny.DynStructHelper;
import org.omg.DynamicAny.DynUnion;
import org.omg.DynamicAny.DynUnionHelper;
import org.omg.DynamicAny.DynValue;
import org.omg.DynamicAny.DynValueBox;
import org.omg.DynamicAny.DynValueBoxHelper;
import org.omg.DynamicAny.DynValueHelper;
import org.omg.DynamicAny.MustTruncate;
import org.omg.DynamicAny.NameDynAnyPair;
import org.omg.DynamicAny.NameValuePair;

class DynAnyTest {
    private static ORB orb;
    private static DynAnyFactory factory;

    @BeforeAll
    static void init() throws Exception {
        orb = ORB.init(new String[0], null);
        factory = DynAnyFactoryHelper.narrow(orb.resolve_initial_references("DynAnyFactory"));
    }

    @AfterAll
    static void destroy() {
        orb.destroy();
    }

    private static Any any() {
        return orb.create_any();
    }

    private static Any anyLong(int v) {
        Any a = any();
        a.insert_long(v);
        return a;
    }

    @Test
    void factory() {
        assertTrue(Arrays.asList(orb.list_initial_services()).contains("DynAnyFactory"));
        assertThrows(InvalidName.class,
                () -> orb.register_initial_reference("DynAnyFactory", factory));
        assertTrue(factory._is_a(DynAnyFactoryHelper.id()));
    }

    @Test
    void classes() throws Exception {
        Object[][] cases = {
            {PointHelper.type(), DynStruct.class},
            {OopsHelper.type(), DynStruct.class},
            {ChoiceHelper.type(), DynUnion.class},
            {ShadeHelper.type(), DynEnum.class},
            {LongSeqHelper.type(), DynSequence.class},
            {ShortArrayHelper.type(), DynArray.class},
            {MoneyHelper.type(), DynFixed.class},
            {ValueTest.PointHelper.type(), DynValue.class},
            {LongBoxHelper.type(), DynValueBox.class},
        };
        for (Object[] c : cases) {
            TypeCode tc = (TypeCode) c[0];
            DynAny d = factory.create_dyn_any_from_type_code(tc);
            assertTrue(((Class<?>) c[1]).isInstance(d), tc.toString());
            assertTrue(d.type().equal(tc));
            d.destroy();
        }
        DynAny count = factory.create_dyn_any_from_type_code(CountHelper.type());
        assertFalse(count instanceof DynStruct);
        assertTrue(count._is_a("IDL:omg.org/DynamicAny/DynAny:1.0"));
        assertFalse(count._is_a(DynStructHelper.id()));
        assertTrue(DynStructHelper.narrow(factory.create_dyn_any_from_type_code(PointHelper.type()))
                ._is_a(DynStructHelper.id()));
        assertThrows(InconsistentTypeCode.class, () -> factory.create_dyn_any_from_type_code(
                orb.get_primitive_tc(TCKind.tk_Principal)));
    }

    @Test
    void roundTrip() throws Exception {
        Any node = any();
        NodeHelper.insert(node, new Node("root", new Node[] {new Node("a", new Node[0]),
            new Node("b", new Node[] {new Node("c", new Node[0])})}));
        Any choice = any();
        Choice ch = new Choice();
        ch.s(3, "three");
        ChoiceHelper.insert(choice, ch);
        Any octets = any();
        OctetsHelper.insert(octets, new byte[] {0, (byte) 0xff});
        Any money = any();
        MoneyHelper.insert(money, new java.math.BigDecimal("-123.45"));
        Any shade = any();
        ShadeHelper.insert(shade, Shade.DIM);
        Any point = any();
        PointHelper.insert(point, new Point(1, 2.5));
        Any inner = any();
        inner.insert_any(point);
        Any oops = any();
        OopsHelper.insert(oops, new Oops("bad", 3));
        for (Any a : new Any[] {node, choice, octets, money, shade, inner, oops}) {
            Any got = factory.create_dyn_any(a).to_any();
            assertTrue(got.equal(a), a.type().toString());
        }
    }

    @Test
    void struct() throws Exception {
        DynStruct d = DynStructHelper.narrow(factory.create_dyn_any_from_type_code(PointHelper.type()));
        d.insert_long(4);
        d.next();
        d.insert_double(0.5);
        assertEquals("y", d.current_member_name());
        assertEquals(TCKind.tk_double, d.current_member_kind());
        Point p = PointHelper.extract(d.to_any());
        assertEquals(4, p.x);
        assertEquals(0.5, p.y);
        assertThrows(TypeMismatch.class, () -> d.insert_long(1));
        NameValuePair[] members = d.get_members();
        assertEquals("x", members[0].id);
        assertEquals("y", members[1].id);
        members[0].value = anyLong(9);
        d.set_members(members);
        assertEquals(9, PointHelper.extract(d.to_any()).x);
        NameDynAnyPair[] pairs = d.get_members_as_dyn_any();
        pairs[1].value.insert_double(7.0);
        assertEquals(7.0, PointHelper.extract(d.to_any()).y);
        members[1].id = "z";
        assertThrows(TypeMismatch.class, () -> d.set_members(members));
        // Components are the DynAny's state.
        d.rewind();
        assertTrue(d.current_component()._is_equivalent(pairs[0].value));
        assertFalse(d.current_component()._is_equivalent(pairs[1].value));
    }

    @Test
    void unionAndEnum() throws Exception {
        DynUnion d = DynUnionHelper.narrow(factory.create_dyn_any_from_type_code(ChoiceHelper.type()));
        DynAny disc = factory.create_dyn_any_from_type_code(orb.get_primitive_tc(TCKind.tk_long));
        disc.insert_long(3);
        d.set_discriminator(disc);
        d.member().insert_string("three");
        assertEquals(TCKind.tk_long, d.discriminator_kind());
        assertEquals("s", d.member_name());
        Choice c = ChoiceHelper.extract(d.to_any());
        assertEquals(3, c.discriminator());
        assertEquals("three", c.s());
        DynEnum e = DynEnumHelper.narrow(factory.create_dyn_any_from_type_code(ShadeHelper.type()));
        e.set_as_string("DIM");
        assertSame(Shade.DIM, ShadeHelper.extract(e.to_any()));
        assertEquals(2, e.get_as_ulong());
        assertThrows(InvalidValue.class, () -> e.set_as_string("PINK"));
    }

    @Test
    void sequences() throws Exception {
        DynSequence d = DynSequenceHelper.narrow(
                factory.create_dyn_any_from_type_code(LongSeqHelper.type()));
        d.insert_long_seq(new int[] {1, 2, 3});
        assertArrayEquals(new int[] {1, 2, 3}, d.get_long_seq());
        d.set_length(4);
        assertArrayEquals(new int[] {1, 2, 3, 0}, LongSeqHelper.extract(d.to_any()));
        d.set_elements(new Any[] {anyLong(5)});
        Any[] elements = d.get_elements();
        assertEquals(1, elements.length);
        assertEquals(5, elements[0].extract_long());
        Any s = any();
        s.insert_short((short) 5);
        assertThrows(TypeMismatch.class, () -> d.set_elements(new Any[] {s}));
        DynAny o = factory.create_dyn_any_from_type_code(OctetsHelper.type());
        o.insert_octet_seq(new byte[] {'a', 'b'});
        assertArrayEquals(new byte[] {'a', 'b'}, OctetsHelper.extract(o.to_any()));
        DynArray arr = (DynArray) factory.create_dyn_any_from_type_code(ShortArrayHelper.type());
        arr.insert_short_seq(new short[] {1, 2, 3});
        assertEquals(3, arr.get_elements_as_dyn_any()[2].get_short());
        assertThrows(InvalidValue.class, () -> arr.insert_short_seq(new short[] {1}));
    }

    @Test
    void anyAndTypeCode() throws Exception {
        DynAny d = factory.create_dyn_any_from_type_code(orb.get_primitive_tc(TCKind.tk_any));
        DynAny inner = factory.create_dyn_any_from_type_code(PointHelper.type());
        inner.insert_long(2);
        d.insert_dyn_any(inner);
        assertTrue(d.get_dyn_any().equal(inner));
        assertEquals(2, PointHelper.extract(d.get_any()).x);
        DynAny t = factory.create_dyn_any_from_type_code(orb.get_primitive_tc(TCKind.tk_TypeCode));
        t.insert_typecode(NodeHelper.type());
        assertTrue(t.get_typecode().equal(NodeHelper.type()));
        DynAny w = factory.create_dyn_any_from_type_code(orb.create_wstring_tc(0));
        w.insert_wstring("wide");
        assertEquals("wide", w.get_wstring());
        assertThrows(NO_IMPLEMENT.class, () -> w.insert_abstract(null));
    }

    @Test
    void valuetypes() throws Exception {
        ValueTest.Node n = new ValueTest.Node();
        n.id = 1;
        n.next = n;
        Any a = any();
        ValueTest.NodeHelper.insert(a, n);
        DynValue d = DynValueHelper.narrow(factory.create_dyn_any(a));
        assertFalse(d.is_null());
        d.seek(1);
        assertTrue(d.current_component()._is_equivalent(d));
        d.rewind();
        d.insert_long(5);
        ValueTest.Node got = ValueTest.NodeHelper.extract(d.to_any());
        assertEquals(5, got.id);
        assertSame(got, got.next);
        d.destroy();
        assertThrows(OBJECT_NOT_EXIST.class, d::component_count);

        DynValueBox box = DynValueBoxHelper.narrow(
                factory.create_dyn_any_from_type_code(LongBoxHelper.type()));
        assertTrue(box.is_null());
        box.set_boxed_value(anyLong(4));
        assertEquals(4, box.get_boxed_value().extract_long());

        DynAny holder = factory.create_dyn_any_from_type_code(PairHelper.type());
        ValueTest.Point p = new ValueTest.Point();
        p.x = 1;
        p.y = 2;
        holder.insert_val(p);
        holder.next();
        holder.insert_val(p);
        Pair pair = PairHelper.extract(holder.to_any());
        assertEquals(1, pair.first.x);
        assertEquals(2, pair.second.y);
        holder.rewind();
        assertEquals(1, ((ValueTest.Point) holder.get_val()).x);
    }

    @Test
    void truncation() throws Exception {
        Point3 p3 = new Point3() {
            private static final long serialVersionUID = 1L;

            {
                label = "three";
            }
        };
        p3.x = 1;
        p3.y = 2;
        p3.z = 3;
        Any a = any();
        ValueTest.PointHelper.insert(a, p3);
        DynAny d = factory.create_dyn_any(a);
        assertEquals(2, d.component_count());
        assertFalse(ValueTest.PointHelper.extract(d.to_any()) instanceof Point3);
        assertThrows(MustTruncate.class, () -> factory.create_dyn_any_without_truncation(a));
        assertThrows(MustTruncate.class,
                () -> factory.create_multiple_dyn_anys(new Any[] {a}, false));
        assertEquals(1, factory.create_multiple_dyn_anys(new Any[] {a}, true).length);
        assertEquals(1, factory.create_multiple_anys(new DynAny[] {d}).length);
    }
}
